-- One prepaid row: bounded identities/scalars <256B; pending <=400000B.
CREATE TRIGGER IF NOT EXISTS restore_working_insert BEFORE INSERT ON restores WHEN NEW.working_prepaid=1 AND (length(NEW.owner)>29 OR length(NEW.vault)<>16 OR length(NEW.operation)<>16 OR length(NEW.expected_root)<>32 OR length(NEW.chain)<>32 OR length(NEW.digest)<>32 OR length(CAST(NEW.pending AS BLOB))>400000 OR NEW.reserved<0) BEGIN SELECT RAISE(ABORT,'restore working capacity'); END;
CREATE TRIGGER IF NOT EXISTS restore_working_update BEFORE UPDATE ON restores WHEN NEW.working_prepaid=1 AND (length(NEW.owner)>29 OR length(NEW.vault)<>16 OR length(NEW.operation)<>16 OR length(NEW.expected_root)<>32 OR length(NEW.chain)<>32 OR length(NEW.digest)<>32 OR length(CAST(NEW.pending AS BLOB))>400000 OR NEW.reserved<0) BEGIN SELECT RAISE(ABORT,'restore working capacity'); END;
